ev("rb26a","2026-02-26","로보락",AS,"로보락이 S10 맥스V 울트라 론칭에서 공식 AS센터 15개를 팅크웨어모바일이 운영한다고 밝혔다(오전 8시~오후 6시). 3월부터 주요 로봇청소기 출장 AS를 시작한다. 롯데하이마트 315개 매장에서 수리를 접수한다. 2026년 1월 공식 홈페이지에 트러스트 센터를 신설했다.",["rb_dd2602","rb_mt2602"],tags=["AS","하이마트"],imp=3,flags=["공식 AS센터 수가 2025년 2월 11곳에서 15곳으로 바뀜(증설 시점은 기사에 없음)"])
ev("rb26b","2026-06-24","로보락",AS,"로보락이 반려동물 오물 사고 안심 보장 서비스(6월 25일 네이버 쇼핑 라이브 구매자 대상)와 시니어 대상 설치·앱 설정·교육 서비스(6월 28일 현대홈쇼핑 구매자 대상)를 시범으로 내놓았다. 기사는 팅크웨어모바일을 국내 유통사로 소개하고 직영 서비스센터가 펫 오물 청소 서비스를 맡는다고 적었다.",["rb_as2606"],tags=["AS","시니어"],flags=["팅크웨어모바일은 '총판'과 '유통사'로 기사마다 달리 표기됨","확대 시행 여부는 시범 결과 뒤 결정이라고만 적힘"])
ev("rb26c","2026-09-06","로보락",ORG,"로보락 글로벌 본사의 2026년 상반기 보고에는 한국에서 프리미엄 로봇청소기 점유율 70% 이상을 유지했고 S10 맥스V 울트라는 출시 10일 만에 약 280억 원 매출을 올렸다고 적혔다. 한국 법인과 조직에 대한 언급은 없다.",["rb_ns2609"],claim="자사 집계",flags=["프리미엄의 가격 기준과 집계 기관은 기사에 없음","본사 보도자료를 뉴시스가 전한 것으로 한국 법인 실적이 아님"],imp=2)
