ev("xm25a","2025-01-06","샤오미코리아",ORG,"샤오미가 2025년 1월 6일 한국 법인 샤오미코리아를 출범했다. 조니 우 사장이 대표다.",["xm_cs2501","xm_mt2501"],imp=3,flags=["법인 설립일과 출범일의 구분은 기사에 없음(CEO스코어데일리 '지난 6일' 표현)","법인 형태(자회사/지사)는 기사마다 '법인'과 '지사'로 달라 확인 필요"])
ev("xm25b","2025-01-15","샤오미코리아",ORG,"샤오미코리아가 서울 포시즌스호텔에서 설립 후 첫 기자간담회를 열었다. 조니 우 사장은 현지 기업으로 자리잡겠다고 밝혔고 키코 송 동아시아 마케팅 총괄이 신제품을 발표했다. 공식 채널은 샤오미코리아 홈페이지, 쿠팡, 네이버이며 이동통신 3사 유통망으로도 판매한다. 국내 AS 미흡 지적에 공식 채널 제품은 3년 품질보증, TV는 당일 배송 설치를 제공한다고 했고 전담 고객 상담 전화를 운영한다.",["xm_mt2501","xm_nc2501","xm_ns2501","xm_cs2501"],tags=["AS","유통"],imp=3,flags=["신제품 수가 머니투데이 16개, CEO스코어데일리 22개로 다름","팬카페 회원이 머니투데이 52만 명, 뉴시스 51만5천 명으로 다름"])
ev("xm25c","2025-06-25","샤오미코리아",CH,"샤오미코리아가 서울 콘래드에서 기자간담회를 열고 6월 28일 IFC몰 여의도점 개점을 알렸다. 앤드류 리 동아시아 총괄과 박대한 리테일 매니저가 참석했다. 매장은 약 60평이고 AS 전문 인력 2명이 상주한다. 온라인과 오프라인의 가격·모델은 같다. 한국 전역에 매장을 낼 계획이다.",["xm_dd2506","xm_sd2506","xm_bh2506"],tags=["매장"],imp=3,flags=["스토어 직원이 디지털데일리 7명(AS 2명)","한국 매장 면적이 시대 60평, 비즈한국 약 197㎡로 환산 표기"])
ev("xm25d","2025-06-26","샤오미코리아",AS,"비즈한국은 샤오미가 국내에서 운영하는 직영 AS센터는 없고 AS는 SK네트웍스서비스에 외주를 맡겨 전국 14개 지점에서 제공한다고 전했다. 샤오미는 개선책으로 오프라인 통합형 매장, 독자 AS센터, 현지 파트너 협력 세 가지를 제시했다.",["xm_bh2506","xm_dd2506"],tags=["AS"],claim="자사 집계",imp=3,flags=["센터 규모·시기는 샤오미가 밝히지 않음"])
ev("xm25e","2025-09-25","샤오미코리아",CH,"샤오미코리아가 2025년 하반기 기자간담회를 열었다. 2호점(NC이스트폴점), 3호점(원그로브점)을 9월 27일 열고, 익스클루시브 서비스센터를 10월 중 용산구 한강대로에 연다고 밝혔다. 이랜드·현대백화점과 리테일, SSG닷컴·네이버와 이커머스, 은행과 무이자 할부, 티머니와 모바일 결제를 협력한다.",["xm_sd2509"],tags=["매장","제휴"],claim="자사 집계",imp=3,flags=["현대백화점은 협력 예정으로 표기됨","1호점 방문객 수치는 샤오미 자체 집계"])
ev("xm25f","2025-10-22","샤오미코리아",AS,"샤오미코리아가 서울 용산구에 첫 공식 서비스센터 '익스클루시브 서비스센터 서울역점'(약 230㎡)을 열었다. 소형기기와 대형 가전 수리가 가능하다고 했고 서울역점을 시작으로 전국 단위 서비스 거점을 넓히겠다고 밝혔다. 기사는 기존 AS센터가 외주 형태였다고 적었다.",["xm_tf2510"],tags=["AS","거점"],imp=3,flags=["운영 방식(직영·외주)은 더팩트가 명시하지 않았고 코리아중앙데일리는 'directly run'으로 적음","삼성전자서비스 용산센터와 직선거리 160m"])
ev("xm25g","2025-11","샤오미코리아",CH,"코리아중앙데일리는 샤오미가 IFC몰 여의도점(6월)에 이어 광진·강서에 매장을 열었고 부천과 잠실에 4·5호점을 곧 열 계획이라고 전했다.",["xm_jd"],tags=["매장"],flags=["게재일 불명(2025년 11월경으로 기록)","4·5호점 개점 확인 못 함"])
ev("xm26","2026-04","샤오미코리아",CH,"딜사이트는 샤오미가 2025년 한국 지사를 설립했고 2026년 4월 기준 오프라인 매장 8곳에서 TV, 에어컨, 전자레인지, 에어프라이어 등을 체험할 수 있다고 전했다.",["dr_ds2604"],tags=["매장"],flags=["매장 8곳의 위치 목록은 기사에 없음","'한국 지사' 표현으로 법인 형태 확인 필요"],imp=2)
