ev("tc23","2023-11-06","TCL",ORG,"TCL이 2023년 11월 6일 한국 법인 설립을 알리고 네이버 스마트스토어에 공식 스토어를 열었다. 이전에는 주로 직수입으로 팔았다.",["tc_ms2311"],imp=3,flags=["법인명·대표는 기사에 없음","스토어 운영 주체는 기사에 없음"])
ev("tc25a","2025-01-15","TCL",CH,"한국 법인은 2023년에 설립됐고 이후 온라인 판매에 집중했다고 보도됐다. 네이버스토어와 쿠팡 기획전 중심으로 팔았고 방문 설치와 기존 TV 무상 수거를 제공한다.",["tc_dm2501"],tags=["온라인"])
